contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Deposit an arbitrary amount into c, then call withdrawAll.
    // Assert: either withdrawAll reverted, or (1) address(c).balance is <= afterDepositBalance
    // and >= afterDepositBalance - depositAmount (i.e., it decreased by at most depositAmount),
    // and (2) this contract's balance did not decrease (it can only stay same or increase).
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        // record balances before any interaction
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;

        // make deposit
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint afterDepositC = address(c).balance;
        // sanity: afterDepositC should be beforeC + depositAmount (this is an accepted rule),
        // but we don't rely on it in the assert (only use observable values).

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint finalC = address(c).balance;
        uint finalThis = address(this).balance;

        // General property: if withdrawAll succeeded, contract balance can decrease by at most depositAmount,
        // and this test's balance cannot have decreased (withdraw transfers only to msg.sender if successful).
        assert(reverted || (
            finalC <= afterDepositC &&
            finalC + depositAmount >= afterDepositC &&
            finalThis >= beforeThis
        ));
    }

    receive() external payable { }
}

